    // ... database operations ...
})
return errors.Wrap(err, "Path.Merge")
```

What if the issue is that we're supposed to return an error when err is nil? That would be:

```go
err := zdb.TX(ctx, func(ctx context.Context) error {
    // ... database operations ...
})
if err == nil {
    return errors.New("Path.Merge: operation succeeded unexpectedly")
}
return errors.Wrap(err, "Path.Merge")
```

